import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Store Submission & Catalog Signing","description":"","frontmatter":{},"headers":[],"relativePath":"publishing/store-submission.md","filePath":"publishing/store-submission.md","lastUpdated":1795182590000}'),n={name:"publishing/store-submission.md"};function o(p,a,l,r,c,h){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="store-submission-catalog-signing" tabindex="-1">Store Submission &amp; Catalog Signing <a class="header-anchor" href="#store-submission-catalog-signing" aria-label="Permalink to &quot;Store Submission &amp; Catalog Signing&quot;">​</a></h1><p>This guide covers packaging a validated worker as a multi-arch OCI Image Layout bundle, pushing it to an OCI registry (<code>ghcr.io</code>, Docker Hub, etc.), and signing <code>catalog.signed.json</code> as a JetPack platform operator.</p><h2 id="_1-developer-workflow-packaging-pushing-to-oci" tabindex="-1">1. Developer Workflow: Packaging &amp; Pushing to OCI <a class="header-anchor" href="#_1-developer-workflow-packaging-pushing-to-oci" aria-label="Permalink to &quot;1. Developer Workflow: Packaging &amp; Pushing to OCI&quot;">​</a></h2><h3 id="step-1-validate-your-manifest" tabindex="-1">Step 1: Validate Your Manifest <a class="header-anchor" href="#step-1-validate-your-manifest" aria-label="Permalink to &quot;Step 1: Validate Your Manifest&quot;">​</a></h3><p>Ensure <code>app.toml</code> passes strict schema and security checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --validate-manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker/app.toml</span></span></code></pre></div><h3 id="step-2-package-an-oci-image-layout-v1-0-0-bundle" tabindex="-1">Step 2: Package an OCI Image Layout v1.0.0 Bundle <a class="header-anchor" href="#step-2-package-an-oci-image-layout-v1-0-0-bundle" aria-label="Permalink to &quot;Step 2: Package an OCI Image Layout v1.0.0 Bundle&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --package-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/my-ocr-worker-oci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oci-ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/your-org/my-ocr-worker:0.1.0</span></span></code></pre></div><p>Output bundle structure:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dist/my-ocr-worker-oci/</span></span>
<span class="line"><span>├── oci-layout               # { &quot;imageLayoutVersion&quot;: &quot;1.0.0&quot; }</span></span>
<span class="line"><span>├── index.json               # Multi-arch OciImageIndex matching [hardware].architectures</span></span>
<span class="line"><span>└── blobs/sha256/</span></span>
<span class="line"><span>    ├── &lt;layer_sha256&gt;       # Deterministic .tar.gz with POSIX &#39;/&#39; paths, 0755 entrypoints</span></span>
<span class="line"><span>    ├── &lt;config_sha256&gt;      # OCI image config JSON with rootfs.diff_ids &amp; io.jetpack.app.* labels</span></span>
<span class="line"><span>    ├── &lt;manifest_sha256&gt;... # Per-platform OciImageManifest blobs</span></span>
<span class="line"><span>    └── &lt;index_sha256&gt;       # Multi-arch OciImageIndex blob (when architectures.len() &gt; 1)</span></span></code></pre></div><p>The command prints <code>manifest_sha256</code> and a ready-to-edit <code>CatalogAppEntry</code> JSON block to stdout.</p><h3 id="step-3-push-with-oras-verify-digest" tabindex="-1">Step 3: Push with <code>oras</code> &amp; Verify Digest <a class="header-anchor" href="#step-3-push-with-oras-verify-digest" aria-label="Permalink to &quot;Step 3: Push with \`oras\` &amp; Verify Digest&quot;">​</a></h3><p>Push the OCI Image Layout directory to your registry:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oras</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-oci-layout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/my-ocr-worker-oci:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/your-org/my-ocr-worker:0.1.0</span></span></code></pre></div><blockquote><p><strong>Important:</strong> Confirm that the pushed remote manifest digest matches <code>manifest_sha256</code>. If your registry or push tool re-serializes the manifest or index, update <code>manifest_sha256</code> in <code>CatalogAppEntry</code> to match the exact remote digest before signing the catalog.</p></blockquote><p>Populate <code>category</code>, <code>icon_svg</code>, and <code>allowed_origins</code> (for example <code>[&quot;https://studio.example.com&quot;]</code>) in the <code>CatalogAppEntry</code> JSON object.</p><hr><h2 id="_2-platform-operator-workflow-key-hygiene-catalog-signing" tabindex="-1">2. Platform Operator Workflow: Key Hygiene &amp; Catalog Signing <a class="header-anchor" href="#_2-platform-operator-workflow-key-hygiene-catalog-signing" aria-label="Permalink to &quot;2. Platform Operator Workflow: Key Hygiene &amp; Catalog Signing&quot;">​</a></h2><h3 id="secret-hygiene-gitignore-protections" tabindex="-1">Secret Hygiene &amp; <code>.gitignore</code> Protections <a class="header-anchor" href="#secret-hygiene-gitignore-protections" aria-label="Permalink to &quot;Secret Hygiene &amp; \`.gitignore\` Protections&quot;">​</a></h3><p>Never commit private signing keys, PEM files, or seed material to source control. The repository <code>.gitignore</code> blocks:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.key</span></span>
<span class="line"><span>*.pem</span></span>
<span class="line"><span>*.secret</span></span>
<span class="line"><span>jetpack-root-signing*</span></span></code></pre></div><p>Verify ignore rules before storing local test keys:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-ignore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jetpack-root-signing.key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.pem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalog.secret</span></span></code></pre></div><h3 id="generating-the-ed25519-root-keypair" tabindex="-1">Generating the Ed25519 Root Keypair <a class="header-anchor" href="#generating-the-ed25519-root-keypair" aria-label="Permalink to &quot;Generating the Ed25519 Root Keypair&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --generate-catalog-keypair</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out-priv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.secrets/jetpack-root-signing.key</span></span></code></pre></div><p>Security guarantees:</p><ul><li><strong>Atomic creation</strong>: Uses <code>OpenOptions::create_new(true)</code> and refuses to overwrite existing files.</li><li><strong>Strict file permissions</strong>: Sets <code>0600</code> (<code>rw-------</code>) on macOS and Linux. On Windows, store the key under <code>%USERPROFILE%\\.secrets\\</code> with user-only NTFS ACLs (<code>icacls &lt;path&gt; /inheritance:r /grant:r &quot;%USERNAME%:F&quot;</code>).</li><li><strong>Zero-exposure output</strong>: The private seed is zeroized in memory (<code>zeroize::Zeroizing</code>) and never printed to stdout.</li></ul><h3 id="rotating-catalog-verify-pubkey" tabindex="-1">Rotating <code>CATALOG_VERIFY_PUBKEY</code> <a class="header-anchor" href="#rotating-catalog-verify-pubkey" aria-label="Permalink to &quot;Rotating \`CATALOG_VERIFY_PUBKEY\`&quot;">​</a></h3><ol><li>Store the production seed in an offline hardware vault (YubiKey, 1Password, HashiCorp Vault, or AWS KMS/Secrets Manager).</li><li>Paste the printed <code>[u8; 32]</code> array literal into <code>CATALOG_VERIFY_PUBKEY</code> inside <code>crates/jetpack-daemon/src/catalog.rs</code>.</li><li>Re-sign <code>crates/jetpack-daemon/assets/catalog.signed.json</code>.</li><li>Run <code>cargo test -p jetpack-daemon catalog::tests</code> to confirm <code>embedded_signed_catalog_verifies_against_platform_pubkey</code> passes, then rebuild <code>make release-daemon</code>.</li></ol><h3 id="signing-catalog-signed-json" tabindex="-1">Signing <code>catalog.signed.json</code> <a class="header-anchor" href="#signing-catalog-signed-json" aria-label="Permalink to &quot;Signing \`catalog.signed.json\`&quot;">​</a></h3><p>Sign locally using <code>--key</code> or in CI/CD via <code>JETPACK_SIGNING_KEY</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Option A: Sign using a local private seed file (64-char hex or raw 32-byte binary)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --sign-catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crates/jetpack-daemon/assets/catalog.signed.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.secrets/jetpack-root-signing.key</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Option B: Sign in CI/CD using an encrypted masked secret environment variable</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JETPACK_SIGNING_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.secrets/jetpack-root-signing.key)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sign-catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crates/jetpack-daemon/assets/catalog.signed.json</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JETPACK_SIGNING_KEY</span></span></code></pre></div><p><code>--sign-catalog</code> parses the catalog against <code>SignedAppCatalog</code> (<code>#[serde(deny_unknown_fields)]</code>), computes the canonical <code>Ed25519</code> signature over <code>SignedAppCatalog::canonical_payload_bytes()</code>, writes <code>ed25519_signature</code> atomically, and re-verifies the file from disk before exiting <code>0</code>.</p>`,33)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
